public class SolutionTest {
    public static void main(String[] args) {
        eq(0, Solution.widestSpan(null));

        Solution.Node single = node(10);
        eq(1, Solution.widestSpan(single));
        check(single.left == null && single.right == null && single.value == 10,
                "single-node tree was modified");

        Solution.Node root = node(1);
        root.left = node(2);
        root.right = node(3);
        root.left.left = node(4);
        root.right.right = node(5);
        root.left.left.right = node(6);
        root.right.right.left = node(7);
        Solution.Node savedLeft = root.left;
        Solution.Node savedRight = root.right;
        eq(6, Solution.widestSpan(root));
        check(root.left == savedLeft && root.right == savedRight, "tree links were modified");
        eq(1, root.value);
        eq(6, root.left.left.right.value);
        eq(7, root.right.right.left.value);

        Solution.Node oneSided = node(0);
        Solution.Node cursor = oneSided;
        for (int i = 0; i < 3000; i++) {
            cursor.left = node(i);
            cursor = cursor.left;
        }
        eq(1, Solution.widestSpan(oneSided));

        Solution.Node huge = node(0);
        Solution.Node left = huge;
        Solution.Node right = huge;
        for (int i = 0; i < 40; i++) {
            left.left = node(i);
            left = left.left;
            right.right = node(-i);
            right = right.right;
        }
        eq(Integer.MAX_VALUE, Solution.widestSpan(huge));
        check(huge.left != null && huge.right != null, "deep tree was modified");
    }

    private static Solution.Node node(int value) {
        Solution.Node node = new Solution.Node();
        node.value = value;
        return node;
    }

    private static void eq(int expected, int actual) {
        if (expected != actual)
            throw new AssertionError("expected <" + expected + "> but was <" + actual + ">");
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

